fn distinct_chars(v: Vec<Str>) -> Vec<Str> {
    let mut seen = vec()
    for x in v {
        if !contains(seen, x) {
            seen = push(seen, x)
        }
    }
    seen
}

fn contains(v: Vec<Str>, x: Str) -> Bool {
    for y in v {
        if y == x {
            return true
        }
    }
    false
}

